// 1. Basic Range Iteration (for_each)
std::vector<int> data = {1, 5, 8};
long long count = 0;

std::for_each(data.begin(), data.end(),
    [&count](int n) { count += n; });

// 2. Transformation (map/modify range)
std::vector<int> src = {10, 20, 30};
std::vector<int> dest;

std::transform(src.begin(), src.end(),
    std::back_inserter(dest),
    [](int n) -> int { return n * n; });
// dest is now {100, 400, 900}

// 3. Copying Between Different Container Types
std::vector<std::string> names = {"A", "B"};
std::list<std::string> backup;

std::copy(names.begin(), names.end(),
    std::back_inserter(backup));
